import json,re
from pathlib import Path
P=Path('.dsh-skill-build/targets/0.2.1-rc.3');r=json.loads((P/'evidence/core/result.json').read_text());S=P/'skill-source'; fmap={f['output']:f['source'] for f in r['files']}
notes={
('export:@deepseek-ai/cordis:.','Context'):'''Context 是代理依赖容器。`extend(meta)` 创建以当前 Context 为原型的子作用域，不修改父级；meta 自有属性遮蔽父属性。`isolate(name,label?)` 为服务名建立独立解析标签，复用同一 label 才共享隔离组；这不提供进程或权限隔离。`intercept(name, config)` 只为其下的插件贡献该服务的配置，合并次序为祖先到后代。`Context.is(value)` 用全局 symbol 跨 realm 与 Cordis 副本识别 Context，优于 instanceof。`root` 在源码上标为 experimental，不能将 root 上任意操作推定为稳定扩展契约。声明合并还把 `ctx.plugin/inject/on/once/effect/get/provide` 置于 Context；仅此对象的直接成员表不表示这些服务混入不存在。''',
('export:@deepseek-ai/cordis:.','Service'):'''构造函数 `super(ctx, name)` 立即以 service key 提供实例，注册跟随 owner fiber 自动撤销；编译期另在 `@deepseek-ai/cordis` 合并 Context 字段。`name` 是实例服务名，不是 npm 名或 Loader entry id。Service.init 是 class 插件构造后初始化入口的 symbol；Service.invoke 使实例可调用。Service.check 是可用性谓词，Service.config 表达 intercept 配置的幻影类型。Service.resolveConfig 将 base、从根向下的 intercept、head 顺序合并，优先调用声明的 Config.merge，否则浅 Object.assign。消费方 inject service key，不能持有卸载后失效的实例继续使用。''',
('export:@deepseek-ai/cordis:.','Fiber'):'''Fiber 是一个插件实例的生命周期句柄，不是插件模块。`ctx.plugin()` 返回它；函数、对象和类插件都有 fiber。PENDING 表示硬依赖缺失，LOADING 表示正在 apply，ACTIVE 表示完成，FAILED 表示 apply 或配置失败，UNLOADING/DISPOSED 表示清理进行或已结束。`dispose()` 等待本实例和子插件的异步清理，并且同一清理只执行一次。effect 内获取外部资源并返回 disposer；逆序启动 disposer 不等于异步清理严格串行，顺序要求写在一个 async disposer 中。''',
('export:@deepseek-ai/cordis:.','EventsService'):'''`on/once` 返回移除监听器的 disposer，监听器归当前 fiber 所有；once 在第一次调用后自行移除。emit 不等待 Promise，parallel 并行等待所有监听器，serial 按顺序等待直到 bail，bail 同步提前返回，waterfall 围绕最后的 next 延续。bail 值定义为除 null、false、undefined 外的任何值，因此 0 和空字符串也会停止。显式 thisArg 同时参与事件过滤，global 监听器会跳过过滤检查，不能随意用作跨 Agent 访问。''',
('export:@deepseek-ai/dsh-tools:.','defineTool'):'''`defineTool(options)` 接受 name、description、parameters、output 与 execute。parameters 的字段 spec 由函数编译成 JSON Schema 并推导 args；根参数对象是隐式开放对象。output.schema 校验每个成功返回值和策略替代值，render(args,value) 是 Native 内容的纯投影，presentationMeta 是可选的可重放 JSON 展示投影。execute(args,exec) 返回 Promise，exec.signal 是取消来源；timeoutMs 若提供须为正有限数且属于协作超时，不会强行终止任意外部副作用。isConcurrencySafe 是纯分类器，不能在分类时抢占资源。''',
('export:@deepseek-ai/dsh-tools:.','ToolRuntime'):'''Host `ctx.tools` 的提供方，硬依赖 systemPrompt。`register(definition)` 的注册和返回 disposer 归调用插件 fiber；`restrict(filter)` 限制当前作用域的可见/可执行工具。`get(name,scope?)` 查询不证明模型在当前 mode 可以直接调用；native、PTC 与混合暴露由当前配置决定。`execute(input)` 经 pre/guard/around/post/result 管道归一化结果；调用方提供 callId/name/arguments/signal，不能直接调用 definition.execute 绕过校验与策略。异步 gate 观察 signal，框架等 Promise 落定再复核取消；模型可见内容必须进 Session 的标准结果路径。''',
('export:@deepseek-ai/dsh-session:.','SessionStore'):'''SessionStore 注册为 `ctx.sessions`，拥有活跃 Session 与追加日志，不等同于磁盘持久化 provider。`create` 公布 Session，`prepare` 用于未发布准备；`get/list` 返回运行中索引。session/created 的同步 throw 可 veto 并触发配对 disposal，异步 rejection 只记录不能撤销同步发布。session/event 是提交后的通知，observer 失败不使已提交 append 失败。`flush(session)` 通过可等待的 session/flush 并行检查点驱动 persistence，不可将普通通知等同耐久确认。''',
('export:@deepseek-ai/dsh-session:.','Session'):'''Session 的日志是模型可见事实来源，追加数据应为可无损 JSON 且满足事件类型。SessionSeq 是事件序号，SessionLogOffset 是日志边界位置，二者不能互换。fork 的 seed 要求从 seq 0 连续且精确保留继承前缀，不能重新编号已关闭 turn/step。工具中断恢复要区分未执行与结果未知，不能把未知结果当成安全重试依据。Session 的持久化、物化消息和活跃 Agent 是不同责任，不能通过复制某一个内存对象完成持久恢复。''',
('export:@deepseek-ai/dsh-agent:.','AgentRegistry'):'''`ctx.agents` 是活跃注册与工厂委派入口，具体创建和驱动由 loop 实现。create 的 sessionId 同时作为活跃 Agent 与 Session 身份；meta.cwd 必须绝对路径，durable seed 在异步 setup 前校验和快照。setup 在公布前装配工具、prompt、restriction、监听器和子插件，不驱动 Agent；可返回同步 commit 在最终公布点重验可变条件。setup throw、commit throw、创建取消或 owner disposal 均回滚未公布作用域。成功返回的 handle 持有创建的生命周期，调用方最终 dispose。''',
('export:@deepseek-ai/dsh-settings:.','SettingsForms'):'''服务键 settings，依赖 configEditor、profileContext。describe 返回活动 Config volatile 字段的表单与 revision，远端必须 redactSecrets。update 合并普通对象，数组整体替换；replace 重置 live 字段后设置 section，不能使用脱敏文档重建完整 section。mutate 使用按序 set/unset 路径，不重述未读 secret；unset 数组索引删除元素，继承键 unset 恢复 base。expectedRevision 不符抛 SettingsConflictError，应重读后协调。configure 只设置所属实例的自动页 policy，同实例重复注册拒绝，调用方把返回 disposer 归入 effect。''',
('export:@deepseek-ai/dsh-typert-protocol:.','Remote'):'''标准装饰器只支持公开实例方法。无参数形式保留方法名；字符串形式显式 wire export name；对象选项仅 name、mode:'stream'、resources，空对象和未知键拒绝。namespace/method/context segment 必须满足字母数字及 _$.- 的文法，且不能是 . 或 ..。标记在构造实例时附到其原型的版本化描述符；冲突标记拒绝。装饰器不会自动生成编解码器或开放网络端点，需所属包的 Loader entry 与 Typert artifact。''',
('export:@deepseek-ai/dsh-typert-protocol:.','RemoteError'):'''RemoteError 是唯一 Remote 失败载体，code 使用已声明的 <domain>/<reason>，details 按 code 判别。错误码合并在拥有抛出点的包；只有多个生产方共同产生时才移到最低共享域。抛出 new RemoteError(code,message,details,{cause})，跨副本识别用 remoteErrorOf，消费方分支按 code，不能依赖 instanceof。未分类的普通异常被 Gateway 折叠为 gateway/internal；carrier取消是 gateway/cancelled，不能创建一族子类代替 code 表。''',
('export:@deepseek-ai/dsh-typert-protocol:.','TypertRemoteService'):'''Host 业务 Service 的便捷基类：protected constructor(ctx,serviceKey,options?) 调用 Cordis Service 并将同一 key 绑定为 Typert namespace（可显式覆盖 namespace）。公开 typertRemote 是冻结绑定，由 Gateway 读取；仅 new 此类不代表远端端点完成装配。第一个绑定为根 Context 建立 invocation accessor，非 Remote 调用时读取 undefined，调用派生 Context 上才有本次 invocation，不能跨异步调用缓存另一个请求的身份。''',
}
for o in r['objects']:
 n=notes.get((o['entry'],o['symbol']))
 if not n:continue
 fp=S/fmap[o['owner']];t=fp.read_text();needle='## '+o['section']+'\n';t=t.replace(needle,needle+'\n'+n+'\n');fp.write_text(t)
print('notes',len(notes))
